// ❌ OLD: No transfer list → the engine structured-clones the buffer.
// Every byte is copied: allocation + memcpy on send, another on receive.
// For a 500MB buffer this doubles peak memory and stalls the sender.
const worker = new Worker('worker.js');
const buffer = new ArrayBuffer(500 * 1024 * 1024); // 500MB

// ❌ OLD: structured clone → full byte copy, sender keeps its buffer
worker.postMessage(buffer);

// Sender still owns `buffer` (not detached), but the worker received a
// completely separate 500MB copy — wasteful for one-way payloads.

// ✅ NEW: Passing the buffer in the transfer list DETACHES it from the
// sender and hands the SAME backing store to the worker — zero copy.
const worker = new Worker('worker.js');
const buffer = new ArrayBuffer(500 * 1024 * 1024); // 500MB

// ✅ NEW: transferable handoff — O(1), no serialization/copy
worker.postMessage(buffer, [buffer]);

// Sender's buffer is now detached: buffer.byteLength === 0.
// The worker sees the same bytes at the same address (remapped into
// its isolate), so peak memory stays at 500MB, not 1GB.
